using TMPro;                                                                                                                                                                                                                                                                           
using UnityEngine;                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                            
public class ScoreManager : MonoBehaviour                                                                                                                                                                                                                                              
{                                                                                                                                                                                                                                                                                      
    [SerializeField] private TMP_Text scoreText;                                                                                                                                                                                                                                       
    private int score;                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                            
    public int CurrentScore => score;                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                            
    void Start()                                                                                                                                                                                                                                                                       
    {                                                                                                                                                                                                                                                                                  
        RefreshText();                                                                                                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                            
    public void AddScore(int amount)                                                                                                                                                                                                                                                   
    {                                                                                                                                                                                                                                                                                  
        score += amount;                                                                                                                                                                                                                                                               
        RefreshText();                                                                                                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                            
    private void RefreshText()                                                                                                                                                                                                                                                         
    {                                                                                                                                                                                                                                                                                  
        scoreText.text = $"Score: {score}";                                                                                                                                                                                                                                            
    }                                                                                                                                                                                                                                                                                  
}  
